script.code:
// PROGRAM_CODES es multivalor (varias matriculas por persona).
// academicProgramSuneduCode es single-value -> se devuelve UN P-code, el menor,
// para que el resultado sea determinista y no dependa del orden de la fuente.
if (input == null) return null
def ids = (input instanceof Collection) ? input : [input]
def tableOid = '9d4e7f21-8a63-4c50-b7e9-3f1a6c8d2b04'
try {
    def options = com.evolveum.midpoint.schema.SelectorOptions.createCollection(
        prismContext.toUniformPath(com.evolveum.midpoint.xml.ns._public.common.common_3.LookupTableType.F_ROW),
        com.evolveum.midpoint.schema.GetOperationOptions.createRetrieve()
    )
    def tableObj = midpoint.getObject(com.evolveum.midpoint.xml.ns._public.common.common_3.LookupTableType.class, tableOid, options)
    if (tableObj == null || tableObj.getRow() == null) {
        log.warn('program-id-to-suneduCode: LookupTable {} vacia o ausente', tableOid)
        return null
    }
    def byKey = [:]
    for (def row : tableObj.getRow()) {
        if (row.getKey() != null) byKey[row.getKey().trim()] = row.getValue()
    }
    def out = [] as Set
    for (def id : ids) {
        if (id == null) continue
        def v = byKey[id.toString().trim()]
        if (v != null) out << v
    }
    if (out.isEmpty()) return null
    return out.sort()[0]
} catch (Exception e) {
    log.warn('program-id-to-suneduCode: error {}', e.getMessage())
    return null
}
